/**
 * Curated registry of recompression / hyperbaric chambers for dive-mode PACE planning.
 *
 * Two entry classes:
 *
 *  manual: true  — Hand-curated entries from DAN, Royal/US Navy, and national dive-medicine
 *                  directories. These cover Europe and key military chambers not on the UHMS
 *                  accredited list. The auto-refresh script NEVER touches these entries.
 *
 *  (no manual)   — UHMS-accredited facilities (auto-generated by
 *                  scripts/refreshHyperbaricChambers.mjs). Re-run to pick up new accreditations
 *                  or corrected coordinates. These appear below the delimiter comment.
 *
 * Merge behaviour (in merge.ts):
 *  - If a registry entry is within 200 m of an already-merged hospital (by name similarity),
 *    the hospital's capabilities array is enriched with 'hyperbaric' rather than adding a
 *    duplicate record.
 *  - Otherwise, a standalone FacilityRecord with isChamber:true is injected.
 *
 * Manual data compiled from:
 *   - DAN (Divers Alert Network) emergency chamber directory
 *   - UHMS (Undersea and Hyperbaric Medical Society) facility locator
 *   - Royal Navy / US Navy diving medicine directories
 *   - Official facility websites
 *
 * UHMS auto-section: https://www.uhms.org/accredited-facilities.html
 *
 * Last reviewed: 2026-07
 *
 * To add a manual entry: fill all required fields, set manual:true, and note the source.
 * The `availability` field is surfaced on the PACE screen / slide notes.
 * To refresh UHMS entries: npm run refresh:chambers (from app/ directory).
 */

import type { LatLon } from '../../calc/geo'

export interface HyperbaricChamber {
  /** Human-readable canonical name shown in the PACE plan. */
  name: string
  /** WGS-84 latitude (decimal degrees). */
  lat: number
  /** WGS-84 longitude (decimal degrees). */
  lon: number
  /** Primary contact / emergency line. */
  phone?: string
  /** Street / city address. */
  address?: string
  /** Availability note, e.g. "24/7 emergency" or "On-call — call before arrival". */
  availability?: string
  /** Shown in the PACE screen notes field. */
  notes?: string
  /** Country the facility is in (used by the validator). */
  country?: string
  /** UHMS "Accredited With Distinction" marker (*). Auto-set by the refresh script. */
  distinction?: boolean
  /**
   * Hand-curated entry — the auto-refresh script never modifies or removes these.
   * Set to true for non-UHMS chambers (DAN, Royal Navy, national directories) and
   * for any UHMS chamber that needs manually-verified coords or custom notes.
   */
  manual?: boolean
}

