// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Haversine distance in metres (inlined to avoid circular-dependency). */
function haversineM(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6_371_000
  const φ1 = (lat1 * Math.PI) / 180
  const φ2 = (lat2 * Math.PI) / 180
  const dφ = ((lat2 - lat1) * Math.PI) / 180
  const dλ = ((lon2 - lon1) * Math.PI) / 180
  const a = Math.sin(dφ / 2) ** 2 + Math.cos(φ1) * Math.cos(φ2) * Math.sin(dλ / 2) ** 2
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Return all chambers within `radiusM` metres of `target`.
 *
 * Used in the fetch pipeline (`App.tsx → mergeFacilities`) to inject in-radius
 * chambers into the facility list whenever coordinates are set (regardless of
 * dive mode — they carry the 'hyperbaric' capability and only surface in the
 * Chamber PACE when dive mode is active).
 */
export function selectChambersInRadius(
  target: LatLon,
  radiusM: number,
): readonly HyperbaricChamber[] {
  return HYPERBARIC_CHAMBERS.filter(
    c => haversineM(target.lat, target.lon, c.lat, c.lon) <= radiusM,
  )
}

/** Exported for unit tests only — do not import in production code. */
export const _testOnly = { HYPERBARIC_CHAMBERS }
